-- Allow manual id insertion on public.sales (only customer_id / customer_code are auto-generated)
DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'sales'
      AND column_name = 'id'
      AND is_identity = 'YES'
      AND identity_generation = 'ALWAYS'
  ) THEN
    ALTER TABLE public.sales ALTER COLUMN id SET GENERATED BY DEFAULT;
  END IF;
END $$;
